    title: "Search Files",
    description: "Recursively search for files and directories matching a pattern. " +
        "The patterns should be glob-style patterns that match paths relative to the working directory. " +
        "Use pattern like '*.ext' to match files in current directory, and '**/*.ext' to match files in all subdirectories. " +
        "Returns full paths to all matching items. Great for finding files when you don't know their exact location. " +
        "Only searches within allowed directories.",
    inputSchema: {
        path: z.string(),
        pattern: z.string(),
        excludePatterns: z.array(z.string()).optional().default([]),
        maxDepth: z.number().int().nonnegative().optional().describe('Optional maximum recursion depth relative to the search root; omitted for unlimited depth'),
        caseSensitive: z.boolean().optional().describe('Optional case-sensitive glob matching; defaults to existing matcher behavior'),
        fileTypes: z.array(z.string()).optional().describe('Optional file type filter using extensions like .ts or special values file/directory')
    },
    outputSchema: { content: z.string() },
    annotations: { readOnlyHint: true }
}, async (args) => {
    const validPath = await validatePath(args.path);
    const results = await searchFilesWithValidation(validPath, args.pattern, allowedDirectories, {
        excludePatterns: args.excludePatterns,
        maxDepth: args.maxDepth,
        caseSensitive: args.caseSensitive,
        fileTypes: args.fileTypes,
    });
    const text = results.length > 0 ? results.join("\n") : "No matches found";
    return {
        content: [{ type: "text", text }],
        structuredContent: { content: text }
    };
});

