const RequestPlanningSchema = z.object({
    originalRequest: z.string().trim().min(20).max(1500),
    splitDetails: z.string().trim().min(15).max(2000),
    tasks: z.array(z.object({
        title: z.string().trim().min(3).max(120),
        description: z.string().trim().min(5).max(2000),
    })).min(1).max(50),
    priority: z.enum(['low', 'medium', 'high', 'critical']),
    estimatedDeadline: z.string().trim().refine((value) => /^\d{4}-\d{2}-\d{2}$/.test(value) || !Number.isNaN(Date.parse(value)), {
        message: "estimatedDeadline must be a valid ISO 8601 datetime or YYYY-MM-DD date string",
    }).optional(),
    tags: z.array(z.string().trim().min(2).max(30)).min(1).max(10),
    assignee: z.string().trim().min(1).max(100).optional(),
    dependencies: z.array(z.string().trim().min(1).max(50)).max(20).optional(),
    notificationPreferences: z.object({
        onTaskComplete: z.boolean().optional(),
        onRequestComplete: z.boolean().optional(),
        onDeadlineApproaching: z.boolean().optional(),
    }).optional(),
}).superRefine((data, ctx) => {
    const normalizedTags = data.tags.map((tag) => tag.trim().toLocaleLowerCase());
    if (new Set(normalizedTags).size !== normalizedTags.length) {
        ctx.addIssue({
            code: z.ZodIssueCode.custom,
            path: ["tags"],
            message: "Tags must be unique (case-insensitive).",
        });
    }
    if (data.dependencies) {
        const normalizedDependencies = data.dependencies.map((dependency) => dependency.trim().toLocaleLowerCase());
        if (new Set(normalizedDependencies).size !== normalizedDependencies.length) {
            ctx.addIssue({
                code: z.ZodIssueCode.custom,
                path: ["dependencies"],
                message: "Dependencies must be unique.",
            });
        }
    }
    if (data.estimatedDeadline) {
        const normalizedDeadline = /^\d{4}-\d{2}-\d{2}$/.test(data.estimatedDeadline)
            ? `${data.estimatedDeadline}T23:59:59.999Z`
            : data.estimatedDeadline;
        if (Number.isNaN(Date.parse(normalizedDeadline))) {
            ctx.addIssue({
                code: z.ZodIssueCode.custom,
                path: ["estimatedDeadline"],
                message: "estimatedDeadline must be parseable as a future date.",
            });
        }
        else if (new Date(normalizedDeadline).getTime() <= Date.now()) {
            ctx.addIssue({
                code: z.ZodIssueCode.custom,
                path: ["estimatedDeadline"],
                message: "estimatedDeadline must be in the future.",
            });
        }
    }
});

