async requestPlanning(originalRequest, tasks, splitDetails, priority, estimatedDeadline, tags, assignee, dependencies, notificationPreferences) {
    await this.loadTasks();
    const normalizedOriginalRequest = originalRequest.trim();
    const normalizedSplitDetails = splitDetails.trim();
    const normalizedTasks = tasks.map((taskDef) => ({
        title: taskDef.title.trim(),
        description: taskDef.description.trim(),
    }));
    const seenTitles = new Set();
    for (const taskDef of normalizedTasks) {
        const normalizedTitle = taskDef.title.toLocaleLowerCase();
        if (seenTitles.has(normalizedTitle)) {
            return {
                status: "error",
                message: "Task titles must be unique within a request.",
            };
        }
        seenTitles.add(normalizedTitle);
    }
    this.requestCounter += 1;
    const requestId = `req-${this.requestCounter}`;
    const newTasks = [];
    for (const taskDef of normalizedTasks) {
        this.taskCounter += 1;
        newTasks.push({
            id: `task-${this.taskCounter}`,
            title: taskDef.title,
            description: taskDef.description,
            done: false,
            approved: false,
            completedDetails: "",
        });
    }
    this.data.requests.push({
        requestId,
        originalRequest: normalizedOriginalRequest,
        splitDetails: normalizedSplitDetails,
        tasks: newTasks,
        completed: false,
        priority: priority,
        estimatedDeadline: estimatedDeadline || null,
        tags: tags || [],
        assignee: assignee || null,
        dependencies: dependencies || [],
        notificationPreferences: notificationPreferences || { onTaskComplete: false, onRequestComplete: false, onDeadlineApproaching: false },
    });
    await this.saveTasks();
    const progressTable = this.formatTaskProgressTable(requestId);
    const priorityBadge = priority === 'critical' ? '🔴' : priority === 'high' ? '🟠' : priority === 'medium' ? '🟡' : '🟢';
    const deadlineInfo = estimatedDeadline ? `\nDeadline: ${estimatedDeadline}` : '';
    const tagsInfo = tags && tags.length > 0 ? `\nTags: ${tags.join(', ')}` : '';
    const assigneeInfo = assignee ? `\nAssignee: ${assignee}` : '';
    const dependenciesInfo = dependencies && dependencies.length > 0 ? `\nDependencies: ${dependencies.join(', ')}` : '';
    const notificationInfo = notificationPreferences ? `\nNotifications: Task Complete=${notificationPreferences.onTaskComplete || false}, Request Complete=${notificationPreferences.onRequestComplete || false}, Deadline Approaching=${notificationPreferences.onDeadlineApproaching || false}` : '';
    return {
        status: "planned",
        requestId,
        priority,
        estimatedDeadline: estimatedDeadline || null,
        tags: tags || [],
        totalTasks: newTasks.length,
        tasks: newTasks.map((t) => ({
            id: t.id,
            title: t.title,
            description: t.description,
        })),
        message: `${priorityBadge} Tasks have been successfully added with priority: ${priority}.${deadlineInfo}${tagsInfo}${assigneeInfo}${dependenciesInfo}${notificationInfo}\nPlease use 'get_next_task' to retrieve the first task.\n${progressTable}`,
    };
}

