            }
            default:
                return {
                    content: [{ type: 'text', text: `Error: Unknown operation "${operation}". Supported operations: get_info, create_table, alter_table, drop_table, get_enums, create_enum` }],
                    isError: true
                };
        }
    }
    catch (error) {
