async handleSearchIcons(args) {
    try {
        const { query, limit, style, exactMatch, offset, includeMetadata, caseSensitive } = this.validateSearchOptions(args);
        let results = await searchIcons(query);
        if (Array.isArray(results)) {
            if (exactMatch) {
                const normalizedQuery = caseSensitive ? query.trim() : query.trim().toLowerCase();
                results = results.filter((icon) => {
                    if (!icon || typeof icon !== "object")
                        return false;
                    const iconName = typeof icon.name === "string"
                        ? icon.name
                        : typeof icon.icon_name === "string"
                            ? icon.icon_name
                            : "";
                    const candidateName = caseSensitive ? iconName : iconName.toLowerCase();
                    return candidateName === normalizedQuery;
                });
            }
            if (style) {
                results = results.filter((icon) => {
                    if (!icon || typeof icon !== "object")
                        return false;
                    const candidateStyle = typeof icon.style === "string"
                        ? icon.style
                        : typeof icon.variant === "string"
                            ? icon.variant
                            : typeof icon.stroke === "string"
                                ? icon.stroke
                                : "";
                    return candidateStyle === style;
                });
            }
            if (typeof offset === "number" && offset > 0) {
                results = results.slice(offset);
            }
            if (typeof limit === "number") {
                results = results.slice(0, limit);
            }
            if (!includeMetadata) {
                results = results.map((icon) => this.extractIconName(icon)).filter((name) => typeof name === "string" && name.length > 0);
            }
        }
        return {
            content: [
                {
                    type: "text",
                    text: JSON.stringify(results, null, 2),
                },
            ],
        };
