async createEntities(entities, options = {}) {
    const graph = await this.loadGraph();
    const { skipDuplicates = true, mergeObservations = false, updateEntityType = false } = options;
    const createdEntities = [];
    for (const entity of entities) {
        const existingEntity = graph.entities.find(existing => existing.name === entity.name);
        if (!existingEntity) {
            graph.entities.push(entity);
            createdEntities.push(entity);
            continue;
        }
        if (!skipDuplicates) {
            graph.entities.push(entity);
            createdEntities.push(entity);
            continue;
        }
        if (updateEntityType) {
            existingEntity.entityType = entity.entityType;
        }
        if (mergeObservations) {
            const newObservations = entity.observations.filter(observation => !existingEntity.observations.includes(observation));
            existingEntity.observations.push(...newObservations);
        }
    }
    await this.saveGraph(graph);
    return createdEntities;
}

