  }

  if (language !== undefined && typeof language !== "string") {
    throw new Error("language参数必须是字符串");
  }

  if (title !== undefined && typeof title !== "string") {
    throw new Error("title参数必须是字符串");
  }

  if (author !== undefined && typeof author !== "string") {
    throw new Error("author参数必须是字符串");
  }

  if (subject !== undefined && typeof subject !== "string") {
    throw new Error("subject参数必须是字符串");
  }

  if (publishYear !== undefined && (!Number.isInteger(publishYear) || publishYear <= 0)) {
    throw new Error("publishYear参数必须是正整数");
  }

  if (ebookOnly !== undefined && typeof ebookOnly !== "boolean") {
    throw new Error("ebookOnly参数必须是布尔值");
  }

  if (exactMatch !== undefined && typeof exactMatch !== "boolean") {
    throw new Error("exactMatch参数必须是布尔值");
  }

  process.stderr.write(`开始搜索书籍: ${query}\n`);

  const hasFieldFilters = Boolean(title || author || subject);
  const params = {
    q: exactMatch && hasFieldFilters ? undefined : query,
    page: page,
    limit: limit,
    ...(sort ? { sort } : {}),
    ...(fields ? { fields } : {}),
    ...(language ? { language } : {}),
    ...(title ? { title } : {}),
    ...(author ? { author } : {}),
    ...(subject ? { subject } : {}),
    ...(publishYear ? { publish_year: publishYear } : {}),
    ...(ebookOnly ? { has_fulltext: true } : {}),
    ...(exactMatch && hasFieldFilters ? { q: undefined } : {})
  };

  if (!params.q) {
    delete params.q;
  }

  const response = await apiClient.get(
    `https://openlibrary.org/search.json`,
    {
      params
    }
  );

  process.stderr.write(`API响应状态: ${response.status}\n`);

  return {
    content: [
      {
        type: "text",
        text: JSON.stringify({
          success: true,
          status: response.status,
          data: response.data,
          appliedFilters: {
            query: exactMatch && hasFieldFilters ? undefined : query,
            title: title || undefined,
            author: author || undefined,
            subject: subject || undefined,
            language: language || undefined,
            publishYear: publishYear || undefined,
            ebookOnly: ebookOnly,
            exactMatch: exactMatch
          },
          message: "书籍搜索完成"
        }, null, 2)
      }
    ]
  };
}

