export async function handleSearchAll(conn, args) {
    const { searchTerm, scope, searchIn = "ALL FIELDS", maxResults, objects } = args;
    try {
        // Validate the search term
        if (!searchTerm.trim()) {
            throw new Error('Search term cannot be empty');
        }
        if (!scope.trim()) {
            throw new Error('Scope cannot be empty');
        }
        // Construct the RETURNING clause with object-specific clauses
        const returningClause = objects
            .map(obj => {
            let clause = `${obj.name}(${obj.fields.join(',')}`;
            // Add object-specific clauses if present
            if (obj.where)
                clause += ` WHERE ${obj.where}`;
            if (obj.orderBy)
                clause += ` ORDER BY ${obj.orderBy}`;
            if (obj.limit)
                clause += ` LIMIT ${obj.limit}`;
            return clause + ')';
        })
            .join(', ');
        // Construct complete SOSL query with scoped comment and standard RETURNING clause
        const soslQuery = `FIND {${searchTerm}} IN ${searchIn} RETURNING ${returningClause}`.trim();
        // Execute search
        const result = await conn.search(soslQuery);
        const scopedRecords = maxResults && maxResults > 0
            ? result.searchRecords.slice(0, maxResults)
            : result.searchRecords;
        // Format results by object
        let formattedResults = `\nScope: ${scope}\n`;
        objects.forEach((obj, index) => {
            const objectResults = scopedRecords.filter((record) => record.attributes.type === obj.name);
            formattedResults += `\n${obj.name} (${objectResults.length} records found):\n`;
            if (objectResults.length > 0) {
                objectResults.forEach((record, recordIndex) => {
                    formattedResults += `  Record ${recordIndex + 1}:\n`;
                    obj.fields.forEach(field => {
                        const value = record[field];
                        formattedResults += `    ${field}: ${value !== null && value !== undefined ? value : 'null'}\n`;
                    });
                });
            }
            if (index < objects.length - 1) {
                formattedResults += '\n';
            }
        });
        return {
            content: [{
                    type: "text",
                    text: `Search Results:${formattedResults}`
                }],
            isError: false,
        };
    }
    catch (error) {
        // Enhanced error handling for SOSL queries
        const errorMessage = error instanceof Error ? error.message : String(error);
        let enhancedError = errorMessage;
        if (errorMessage.includes('MALFORMED_SEARCH')) {
            enhancedError = `Invalid search query format. Common issues:\n` +
                `1. Search term contains invalid characters\n` +
                `2. Object or field names are incorrect\n` +
                `3. Missing required SOSL syntax elements\n` +
                `4. Scope or result settings may not match the intended search setup\n\n` +
                `Original error: ${errorMessage}`;
        }
        else if (errorMessage.includes('INVALID_FIELD')) {
            enhancedError = `Invalid field specified in RETURNING clause. Please check:\n` +
                `1. Field names are correct\n` +
                `2. Fields exist on the specified objects\n` +
                `3. You have access to all specified fields\n\n` +
                `Original error: ${errorMessage}`;
        }
        return {
            content: [{
                    type: "text",
                    text: `Error executing search: ${enhancedError}`
                }],
            isError: true,
        };
    }
}

