server.tool('whois_domain', 'Looksup whois information about the domain', {
    domain: z.string().min(1),
    format: z.enum(['json', 'raw']).optional(),
    pretty: z.boolean().optional(),
    timeout: z.number().positive().optional(),
    follow: z.number().int().nonnegative().optional(),
    include_raw: z.boolean().optional(),
    normalize_domain: z.boolean().optional(),
    response_mode: z.enum(['parsed', 'raw', 'both']).optional(),
    raw_label: z.string().min(1).optional()
}, async ({ domain, format = 'json', pretty = false, timeout = 15000, follow = 2, include_raw = false, normalize_domain = false, response_mode, raw_label = 'raw' }) => {
    try {
        const normalizedDomain = normalize_domain
            ? domain
                .trim()
                .replace(/^[a-z]+:\/\//i, '')
                .replace(/[/?#].*$/, '')
                .toLowerCase()
            : domain;
        const lookupDomain = normalizedDomain.trim();
        const result = await whoisDomain(lookupDomain, { timeout, follow });
        const rawText = String(result);
        const effectiveResponseMode = response_mode ?? (format === 'raw' ? 'raw' : include_raw ? 'both' : 'parsed');
        let text;
        if (format === 'raw' || effectiveResponseMode === 'raw') {
            text = `Domain whois lookup for: \n${rawText}`;
        }
        else {
            const payload = effectiveResponseMode === 'both'
                ? {
                    parsed: result,
                    [raw_label]: rawText
                }
                : result;
            text = `Domain whois lookup for: \n${JSON.stringify(payload, null, pretty ? 2 : 0)}`;
        }
        return {
            content: [{ type: 'text', text }],
        };
    }
    catch (err) {
        const error = err;
        return {
            content: [{ type: 'text', text: `Error: ${error.message}` }],
            isError: true
        };
    }
});

