        const taskMap = new Map(tasks.map(task => [task.id, task]));
        const isDone = (task) => task.completed || task.status === 'done';
        const hasIncompleteDependencies = (task) => task.dependsOn?.some(depId => {
            const dependency = taskMap.get(depId);
            return !dependency || !isDone(dependency);
        }) ?? false;
        const visibleTasks = includeCompletedTasks ? tasks : tasks.filter(task => !isDone(task));
        const readyTasksAll = visibleTasks
            .filter(task => !isDone(task) && task.status !== 'blocked' && !hasIncompleteDependencies(task))
            .sort((a, b) => (b.priority || 0) - (a.priority || 0) || (a.complexity || 99) - (b.complexity || 99));
        const blockedTasksAll = visibleTasks
            .filter(task => !isDone(task) && (task.status === 'blocked' || hasIncompleteDependencies(task)))
            .sort((a, b) => (b.priority || 0) - (a.priority || 0));
        const inProgressTasksAll = visibleTasks
            .filter(task => !isDone(task) && task.status === 'in-progress')
            .sort((a, b) => (b.priority || 0) - (a.priority || 0));
        const readyTasks = readyTasksAll.slice(0, maxTasks);
        const blockedTasks = blockedTasksAll.slice(0, maxTasks);
        const inProgressTasks = inProgressTasksAll.slice(0, maxTasks);
        const completedCount = tasks.filter(task => isDone(task)).length;
        const openCount = tasks.length - completedCount;
        const topLevelCount = tasks.filter(task => !task.parentId).length;
        const nestedCount = tasks.length - topLevelCount;
        const pendingCount = tasks.filter(task => task.status === 'pending' && !isDone(task)).length;
        const inProgressCount = tasks.filter(task => task.status === 'in-progress' && !isDone(task)).length;
        const blockedCount = tasks.filter(task => task.status === 'blocked' && !isDone(task)).length;
        const totalEstimatedHours = tasks.reduce((sum, task) => sum + (typeof task.estimatedHours === 'number' ? task.estimatedHours : 0), 0);
        const totalActualHours = tasks.reduce((sum, task) => sum + (typeof task.actualHours === 'number' ? task.actualHours : 0), 0);
        const formatTask = (task) => `• ${task.name} (${task.id})${typeof task.priority === 'number' ? ` [P${task.priority}]` : ''}${typeof task.complexity === 'number' ? ` [C${task.complexity}]` : ''}${task.status ? ` - ${task.status}` : ''}`;
        const lines = [
            '📊 **Project Status Review**',
            '',
            `**${project.name}** (ID: ${project.id})`,
            `Description: ${project.description}`,
            '',
            `Task totals: ${tasks.length} total • ${openCount} open • ${completedCount} completed`,
            `Structure: ${topLevelCount} top-level • ${nestedCount} nested`,
            `Statuses: ${pendingCount} pending • ${inProgressCount} in-progress • ${blockedCount} blocked • ${completedCount} done`,
            totalEstimatedHours > 0 || totalActualHours > 0
                ? `Time: ${totalActualHours}h logged • ${totalEstimatedHours}h estimated`
                : 'Time: no hour estimates logged',
            '',
            `Ready to start next (${readyTasksAll.length} total, showing up to ${maxTasks}):`,
            ...(readyTasks.length > 0 ? readyTasks.map(formatTask) : ['• No ready tasks found']),
            '',
            `Needs attention (${blockedTasksAll.length} total, showing up to ${maxTasks}):`,
            ...(blockedTasks.length > 0 ? blockedTasks.map(formatTask) : ['• No blocked tasks found']),
            '',
            `Currently in progress (${inProgressTasksAll.length} total, showing up to ${maxTasks}):`,
            ...(inProgressTasks.length > 0 ? inProgressTasks.map(formatTask) : ['• No in-progress tasks found']),
            '',
            'Tips:',
            '• Use `list_tasks` with `showHierarchy: true` to inspect the full task tree',
            '• Use `get_next_task_recommendation` for ranked next-step guidance',
            '• Use `update_task` or `move_task` to unblock or reorganize work'
        ];
        return {
            content: [{
                    type: 'text',
                    text: lines.join('\n')
                }]
        };
    }
    catch (error) {
        return {
            content: [{
                    type: 'text',
                    text: `Error: ${error instanceof Error ? error.message : 'Unknown error'}`
                }],
            isError: true
        };
    }
});

