async getRelatedNodes(names, context, location) {
    const graph = await this.loadGraph(context, location);
    const seedNames = new Set(names);
    const relatedRelations = graph.relations.filter(r => seedNames.has(r.from) || seedNames.has(r.to));
    const relatedEntityNames = new Set(names);
    for (const relation of relatedRelations) {
        relatedEntityNames.add(relation.from);
        relatedEntityNames.add(relation.to);
    }
    const relatedEntities = graph.entities.filter(e => relatedEntityNames.has(e.name));
    return {
        entities: relatedEntities,
        relations: relatedRelations,
    };
}

diff_hunks.new_code:
async getRelatedNodes(names, context, location, maxHops = 1, includeSeeds = true) {
    const graph = await this.loadGraph(context, location);
    const normalizedMaxHops = Number.isFinite(maxHops) && maxHops > 0 ? Math.floor(maxHops) : 1;
    const discoveredEntityNames = new Set(includeSeeds ? names : []);
    const visitedEntityNames = new Set(names);
    let frontier = new Set(names);
    const relatedRelations = [];
    const seenRelationKeys = new Set();
    for (let hop = 0; hop < normalizedMaxHops && frontier.size > 0; hop++) {
        const nextFrontier = new Set();
        for (const relation of graph.relations) {
            const touchesFrontier = frontier.has(relation.from) || frontier.has(relation.to);
            if (!touchesFrontier) {
                continue;
            }
            const relationKey = `${relation.from}::${relation.relationType}::${relation.to}`;
            if (!seenRelationKeys.has(relationKey)) {
                relatedRelations.push(relation);
                seenRelationKeys.add(relationKey);
            }
            discoveredEntityNames.add(relation.from);
            discoveredEntityNames.add(relation.to);
            if (!visitedEntityNames.has(relation.from)) {
                nextFrontier.add(relation.from);
                visitedEntityNames.add(relation.from);
            }
            if (!visitedEntityNames.has(relation.to)) {
                nextFrontier.add(relation.to);
                visitedEntityNames.add(relation.to);
            }
        }
        frontier = nextFrontier;
    }
    const relatedEntities = graph.entities.filter(e => discoveredEntityNames.has(e.name));
    return {
        entities: relatedEntities,
        relations: relatedRelations,
    };
}

