  url: z.string().describe("The URL to fetch"),
  max_length: z.number().default(2000).describe("The max length of the content to return"),
  start_index: z.number().default(0).describe(`The starting index of content to return`),
  method: z.string().nullish().describe("Optional HTTP method to use for the request").default("GET"),
  headers: z.record(z.string()).nullish().describe("Optional HTTP headers to include with the request"),
  timeout_ms: z.number().nullish().describe("Optional request timeout in milliseconds"),
  follow_redirects: z.boolean().nullish().describe("Whether to follow HTTP redirects").default(true),
  query_params: z.record(z.string()).nullish().describe("Optional query string parameters to append to the URL"),
  response_format: z.enum(["auto", "markdown", "html", "text"]).nullish().describe("Optional output format for text responses").default("auto"),
  body: z.string().nullish().describe("Optional request body to send with the request, useful for POST, PUT, or PATCH operations"),
  include_metadata: z.boolean().nullish().describe("Whether to include response metadata such as final URL, status code, content type, and pagination details in text output").default(true)
}, async (args) => {
  const normalizedUrl = /^https?\:\/\//.test(args.url) ? args.url : `https://${args.url}`;
  const parsedUrl = new URL(normalizedUrl);
  if (args.query_params) {
    for (const [key, value] of Object.entries(args.query_params)) {
      parsedUrl.searchParams.set(key, value);
    }
  }
  const url = parsedUrl.toString();
  const res = await gotScraping2({
    url,
    method: args.method || "GET",
    headers: args.headers,
    followRedirect: args.follow_redirects ?? true,
    ...args.body != null ? { body: args.body } : {},
    ...args.timeout_ms != null ? { timeout: { request: args.timeout_ms } } : {}
  });
  if (res.ok) {
    const contentType = res.headers["content-type"];
    if (!contentType || !contentType.includes("text/")) {
      const isImage = contentType?.includes("image/");
      return {
        content: [
          isImage && contentType ? {
            type: "image",
            data: res.rawBody.toString("base64"),
            mimeType: contentType
          } : {
            type: "text",
            text: `Unsupported mime type: ${contentType}`
          }
        ]
      };
    }
    const isHTML = contentType.includes("html");
    const responseFormat = args.response_format || "auto";
    let content;
    if (responseFormat === "html") {
      content = res.body;
    } else if (responseFormat === "markdown") {
      content = isHTML ? toMarkdown(res.body) : res.body;
    } else if (responseFormat === "text") {
      content = isHTML ? res.body.replace(/<script[\s\S]*?<\/script>/gi, "").replace(/<style[\s\S]*?<\/style>/gi, "").replace(/<[^>]+>/g, " ").replace(/\s+/g, " ").trim() : res.body;
    } else {
      content = !isHTML ? res.body : toMarkdown(res.body);
    }
    let remainingContentLength = 0;
    if (args.start_index) {
      content = content.slice(args.start_index);
    }
    if (args.max_length) {
      const newContent = content.slice(0, args.max_length);
      if (newContent !== content) {
        remainingContentLength = content.length - newContent.length;
      }
      content = newContent;
    }
    const includeMetadata = args.include_metadata ?? true;
    return {
      content: [
        {
          type: "text",
          text: includeMetadata ? [
            `URL: ${url}`,
            `Status: ${res.statusCode}`,
            `Content-Type: ${contentType}`,
            `Start index: ${args.start_index}`,
            `Remaining content length: ${remainingContentLength}`,
            `Content: ${content}`
          ].join(`
`) : content
        }
      ]
    };
  }
  return {
    content: [
      {
        type: "text",
        text: `Failed to fetch ${url}: ${res.statusCode}
${res.body}`
      }
    ],
    isError: true
  };
});

