server.tool(
    "getComponentsByNames",
    "Retrieves comprehensive implementation details for multiple known Magic UI components in a single request, including full source code, installation instructions, and associated examples for each found component. Use this after getComponentIndex or searchComponents when you already know a specific set of component names and want a targeted batch fetch without pulling an entire category.",
    {
        componentNames: {
            type: "array",
            items: {
                type: "string",
            },
            description: "An array of exact component names to retrieve (e.g., ['marquee', 'animated-beam', 'shimmer-button']).",
        },
    },
    async ({ componentNames }) => {
        try {
            const normalizedNames = Array.isArray(componentNames)
                ? [...new Set(componentNames
                    .filter((name) => typeof name === "string")
                    .map((name) => name.trim())
                    .filter((name) => name.length > 0))]
                : [];
            if (normalizedNames.length === 0) {
                return {
                    content: [
                        {
                            type: "text",
                            text: "No valid component names were provided. Supply one or more exact component names.",
                        },
                    ],
                    isError: true,
                };
            }
            const [components, allExampleComponents] = await Promise.all([
                fetchUIComponents(),
                fetchExampleComponents(),
            ]);
            const exampleNamesByComponent = buildExampleComponentMap(allExampleComponents);
            const componentMap = new Map(components.map((component) => [component.name, component]));
            const foundComponents = [];
            const notFound = [];
            for (const componentName of normalizedNames) {
                const component = componentMap.get(componentName);
                if (!component) {
                    notFound.push(componentName);
                    continue;
                }
                try {
                    const componentDetails = await fetchComponentDetails(componentName);
                    const componentContent = componentDetails.files[0]?.content;
                    const relevantExampleNames = exampleNamesByComponent.get(componentName) || [];
                    const installInstructions = `Install the component using your preferred package manager: pnpm dlx shadcn@latest add "https://magicui.design/r/${componentName}.json" or npm/npx: npx shadcn@latest add "https://magicui.design/r/${componentName}.json" or yarn: yarn dlx shadcn@latest add "https://magicui.design/r/${componentName}.json" or bun: bunx shadcn@latest add "https://magicui.design/r/${componentName}.json". After installation, you can import the component like this: import { ${formatComponentName(component.name)} } from "@/components/ui/${componentName}";`;
                    const exampleDetailsList = await Promise.all(relevantExampleNames.map((name) => fetchExampleDetails(name)));
                    const formattedExamples = exampleDetailsList
                        .filter((details) => details !== null)
                        .map((details) => ({
                        name: details.name,
                        type: details.type,
                        description: details.description,
                        content: details.files[0]?.content,
                    }));
                    const validatedComponent = IndividualComponentSchema.parse({
                        name: component.name,
                        type: component.type,
                        description: component.description,
                        content: componentContent,
                        install: installInstructions,
                        examples: formattedExamples,
                    });
                    foundComponents.push(validatedComponent);
                }
                catch (error) {
                    notFound.push(componentName);
                }
            }
            return {
                content: [
                    {
                        type: "text",
                        text: JSON.stringify({
                            requested: normalizedNames,
                            foundCount: foundComponents.length,
                            notFound,
                            components: foundComponents,
                        }, null, 2),
                    },
                ],
            };
        }
        catch (error) {
            let errorMessage = "Error fetching multiple components";
            if (error instanceof Error) {
                errorMessage += `: ${error.message}`;
            }
            return {
                content: [{ type: "text", text: errorMessage }],
                isError: true,
            };
        }
    }
);

