    description: "Evaluate a single translation against its source and reference, returning a score, error spans, and a concise summary. Best for one candidate at a time before batch scoring or pairwise comparison.",
    inputSchema: {
        source: EvaluateInputSchema.shape.source,
        translation: EvaluateInputSchema.shape.translation,
        reference: EvaluateInputSchema.shape.reference,
        response_format: EvaluateInputSchema.shape.response_format,
        use_gpu: EvaluateInputSchema.shape.use_gpu,
        model_variant: {
            type: "string",
            description: "xCOMET model variant to use (e.g., 'xl', 'xxl', 'base')",
            optional: true,
        },
        confidence_threshold: {
            type: "number",
            description: "Minimum confidence score (0-1) for error detections",
            optional: true,
            minimum: 0,
            maximum: 1,
        },
        include_metadata: {
            type: "boolean",
            description: "Include detailed evaluation metadata in response",
            optional: true,
        },
    },
    outputSchema: {
        score: EvaluateOutputSchema.shape.score,
        errors: EvaluateOutputSchema.shape.errors,
        summary: EvaluateOutputSchema.shape.summary,
    },
    annotations: READ_ONLY_ANNOTATIONS,
}, async (params) => {
    try {
        const evaluationOptions = {
            use_gpu: params.use_gpu,
            model_variant: params.model_variant,
            confidence_threshold: params.confidence_threshold,
            include_metadata: params.include_metadata,
        };
        const result = await xCometService.evaluate(params.source, params.translation, params.reference, evaluationOptions.use_gpu, evaluationOptions);

        // Filter errors by confidence threshold if specified
        if (params.confidence_threshold !== undefined && result.errors) {
            result.errors = result.errors.filter((err) => !err.confidence || err.confidence >= params.confidence_threshold);
        }

        return createToolResponse(result, params.response_format, "Translation Quality Evaluation");
    }
    catch (error) {
        return createErrorResponse(error, "evaluating translation");
    }
});
