server.registerTool("xcomet_compare_translations", {
    title: "Compare Two Translations",
    description: "Compare two candidate translations for the same source/reference and return a relative quality assessment. Ideal for A/B selection, reranking, or deciding between two revisions of the same translation.",
    inputSchema: {
        source: {
            type: "string",
            description: "Original source text to be translated",
        },
        translation_a: {
            type: "string",
            description: "First translation candidate to compare",
        },
        translation_b: {
            type: "string",
            description: "Second translation candidate to compare",
        },
        reference: {
            type: "string",
            description: "Reference translation used for evaluation",
        },
        response_format: {
            type: "string",
            description: "Format of the response output",
            optional: true,
            enum: ["text", "markdown"],
        },
        use_gpu: {
            type: "boolean",
            description: "Use GPU acceleration for comparison",
            optional: true,
        },
        include_metadata: {
            type: "boolean",
            description: "Include detailed comparison metadata in response",
            optional: true,
        },
    },
    outputSchema: {
        score_a: {
            type: "number",
            description: "Quality score for translation A",
        },
        score_b: {
            type: "number",
            description: "Quality score for translation B",
        },
        preferred_translation: {
            type: "string",
            description: "The translation judged to be better overall",
        },
        score_delta: {
            type: "number",
            description: "Difference between the two scores",
        },
        summary: {
            type: "string",
            description: "Concise comparison summary",
        },
    },
    annotations: READ_ONLY_ANNOTATIONS,
}, async (params) => {
    try {
        const resultA = await xCometService.evaluate(params.source, params.translation_a, params.reference, params.use_gpu, {
            use_gpu: params.use_gpu,
            include_metadata: params.include_metadata,
        });
        const resultB = await xCometService.evaluate(params.source, params.translation_b, params.reference, params.use_gpu, {
            use_gpu: params.use_gpu,
            include_metadata: params.include_metadata,
        });
        const scoreA = typeof resultA.score === "number" ? resultA.score : 0;
        const scoreB = typeof resultB.score === "number" ? resultB.score : 0;
        const preferred_translation = scoreA >= scoreB ? "translation_a" : "translation_b";
