server.registerTool("xcomet_rank_translations", {
    title: "Rank Multiple Translations",
    description: "Evaluate and rank multiple candidate translations for the same source/reference pair. Use this for reranking, n-best selection, or choosing the best option among three or more alternatives in a single request.",
    inputSchema: {
        source: {
            type: "string",
            description: "Original source text to be translated",
        },
        translations: {
            type: "array",
            description: "Candidate translations to score and rank",
            items: {
                type: "string",
            },
            minItems: 2,
        },
        reference: {
            type: "string",
            description: "Reference translation used for evaluation",
        },
        response_format: {
            type: "string",
            description: "Format of the response output",
            optional: true,
            enum: ["text", "markdown"],
        },
        use_gpu: {
            type: "boolean",
            description: "Use GPU acceleration for ranking",
            optional: true,
        },
        include_metadata: {
            type: "boolean",
            description: "Include per-candidate evaluation metadata in response",
            optional: true,
        },
    },
    outputSchema: {
        rankings: {
            type: "array",
            description: "Ranked translation candidates with scores",
            items: {
                type: "object",
                properties: {
                    rank: {
                        type: "number",
                        description: "Ranking position, starting at 1",
                    },
                    translation_index: {
                        type: "number",
                        description: "Original zero-based index of the translation candidate",
                    },
                    score: {
                        type: "number",
                        description: "xCOMET quality score for the translation",
                    },
                },
            },
        },
        best_translation_index: {
            type: "number",
            description: "Zero-based index of the highest-scoring translation",
        },
        best_score: {
            type: "number",
            description: "xCOMET score of the highest-ranked translation",
        },
        summary: {
            type: "string",
            description: "Concise ranking summary",
        },
    },
    annotations: READ_ONLY_ANNOTATIONS,
}, async (params) => {
    try {
        const evaluations = await Promise.all(params.translations.map((translation) => xCometService.evaluate(params.source, translation, params.reference, params.use_gpu, {
            use_gpu: params.use_gpu,
            include_metadata: params.include_metadata,
        })));
        const rankings = evaluations
            .map((evaluation, index) => ({
            translation_index: index,
            score: typeof evaluation.score === "number" ? evaluation.score : 0,
            metadata: evaluation.metadata,
        }))
            .sort((a, b) => b.score - a.score)
            .map((entry, index) => ({
            rank: index + 1,
            translation_index: entry.translation_index,
            score: entry.score,
            ...(params.include_metadata ? { metadata: entry.metadata } : {}),
        }));
        const best = rankings[0];
        const result = {
            rankings,
            best_translation_index: best.translation_index,
            best_score: best.score,
            summary: `Translation ${best.translation_index + 1} ranked highest out of ${params.translations.length} candidates based on xCOMET quality scoring.`,
        };
        return createToolResponse(result, params.response_format, "Translation Ranking");
    }
    catch (error) {
        return createErrorResponse(error, "ranking translations");
    }
});

