server.tool(
    "read_file",
    "Read the complete contents of a file from the file system. Handles various text encodings and provides detailed error messages if the file cannot be read.",
    {
        path: z.string().describe("The path to the file"),
        encoding: z.string().optional().default('utf-8').describe("File encoding (default: utf-8)"),
        startLine: z.number().optional().describe("Starting line number (1-indexed) for reading a specific range"),
        endLine: z.number().optional().describe("Ending line number (1-indexed) for reading a specific range"),
        maxSize: z.number().optional().describe("Maximum file size in bytes to read (default: no limit)")
    },
    async ({ path: filePath, encoding, startLine, endLine, maxSize }) => {
        try {
            const resolvedPath = await resolvePath(filePath);

            // Check file size if maxSize is specified
            if (maxSize !== undefined) {
                const stats = await fs.stat(resolvedPath);
                if (stats.size > maxSize) {
                    return {
                        content: [{ type: "text", text: `Error: File size (${stats.size} bytes) exceeds maximum allowed size (${maxSize} bytes)` }],
                        isError: true
                    };
                }
            }

            let content = await fs.readFile(resolvedPath, encoding);

            // Handle line range selection if specified
            if (startLine !== undefined || endLine !== undefined) {
                const lines = content.split('\n');
                const start = startLine !== undefined ? Math.max(1, startLine) - 1 : 0;
                const end = endLine !== undefined ? Math.min(lines.length, endLine) : lines.length;

                if (start >= lines.length) {
                    return {
                        content: [{ type: "text", text: `Error: startLine (${startLine}) exceeds total lines (${lines.length})` }],
                        isError: true
                    };
                }

                content = lines.slice(start, end).join('\n');
                const lineInfo = `[Lines ${start + 1}-${end} of ${lines.length}]\n`;
                content = lineInfo + content;
            }

            return {
                content: [{ type: "text", text: content }]
            };
        } catch (error) {
            return {
                content: [{ type: "text", text: `Error: ${error.message}` }],
                isError: true
            };
        }
    }
);

