    results.examples.sort((a, b) => a.name.localeCompare(b.name));
  }
  if (results.changelogs) {
    results.changelogs.sort((a, b) => a.packageName.localeCompare(b.packageName));
  }
} else if (sortBy === "date" && includeMetadata) {
  if (results.docs) {
    results.docs.sort((a, b) => {
      const dateA = a.metadata?.lastModified || "";
      const dateB = b.metadata?.lastModified || "";
      return dateB.localeCompare(dateA);
    });
  }
  if (results.examples) {
    results.examples.sort((a, b) => {
      const dateA = a.metadata?.lastModified || "";
      const dateB = b.metadata?.lastModified || "";
      return dateB.localeCompare(dateA);
    });
  }
  if (results.changelogs) {
    results.changelogs.sort((a, b) => {
      const dateA = a.metadata?.lastModified || "";
      const dateB = b.metadata?.lastModified || "";
      return dateB.localeCompare(dateA);
    });
  }
}

return {
