async function getWeatherAdvice(data) {
    const unit = data.unit === "F" ? "F" : "C";
    const activity = data.activity || "outdoor";
    const baseTempC = Math.max(-10, Math.min(35, Math.round(30 - Math.abs(data.latitude) / 3)));
    const displayTemp = unit === "F"
        ? `${Math.round((baseTempC * 9) / 5 + 32)}°F`
        : `${baseTempC}°C`;
    let advice = `天气建议：当前位置(${data.latitude},${data.longitude})预计体感温度约为${displayTemp}，适合${activity}场景。`;
    if (baseTempC >= 30) {
        advice += " 建议穿着轻薄透气衣物，并尽量避开正午高温时段。";
    }
    else if (baseTempC >= 20) {
        advice += " 建议穿着舒适的春夏装，外出总体较为轻松。";
    }
    else if (baseTempC >= 10) {
        advice += " 建议增加一件薄外套，早晚注意保暖。";
    }
    else {
        advice += " 气温偏低，建议穿保暖外套并注意防风。";
    }
    if (activity === "commute") {
        advice += " 通勤时建议预留一点路上时间，并留意路面和能见度变化。";
    }
    else if (activity === "travel") {
        advice += " 出行前建议准备便携外套和常用随身物品，方便应对天气变化。";
    }
    else if (activity === "exercise") {
        advice += " 运动前请充分热身，并根据气温调整运动强度。";
    }
    if (data.includeHydration) {
        advice += baseTempC >= 25 ? " 另外请注意及时补水。" : " 可适量补水以保持良好状态。";
    }
    return {
        content: [
            {
                type: "text",
                text: advice,
            },
        ],
    };
}

